import { useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { motion, AnimatePresence } from 'framer-motion'
import { ArrowLeft, Clock, RefreshCw, Smartphone, PackageX, Zap, ClipboardList } from 'lucide-react'
import { useOrders } from '@/features/orders/hooks/useOrders'
import { useAuthStore, useUIStore } from '@/store'
import { Container } from '@/components/layout/Container'
import { OrderCard } from '@/features/orders/components/OrderCard'
import { OrderCardSkeleton } from '@/components/ui/Skeleton'
import { trackPageView } from '@/lib/analytics'
import { useSEO } from '@/hooks/useSEO'
import { getOrCreateGuestIdentity } from '@/features/v2/api/unifiedOrderApi'
import { hapticLight, hapticMedium, hapticHeavy } from '@/utils/haptics'
import { cn } from '@/utils/cn'

const slideUpItem = {
  hidden: { opacity: 0, y: 20, scale: 0.98 },
  visible: { opacity: 1, y: 0, scale: 1, transition: { type: 'spring', stiffness: 320, damping: 28 } }
}
const staggerList = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { staggerChildren: 0.08, delayChildren: 0.05 } }
}

export default function OrdersPage() {
  const navigate = useNavigate()
  const { user, isGuest } = useAuthStore()
  const { addToast } = useUIStore()

  const guestIdentity = isGuest ? getOrCreateGuestIdentity() : null

  const { data: orders, isLoading, refetch, isRefetching } = useOrders(
    user?.id,
    user?.lineUserId,
    undefined,
    guestIdentity?.id
  )

  useEffect(() => {
    trackPageView('/orders', 'Orders')
    window.scrollTo(0, 0)
  }, [])

  useSEO({
    title: 'ประวัติการสั่งซื้อ | กะเพรา 52',
    description: 'ติดตามสถานะออเดอร์และดูประวัติการสั่งซื้อกะเพราของคุณ'
  })

  const activeOrders = orders?.filter(o => ['placed', 'confirmed', 'preparing', 'ready'].includes(o.status)) || []
  const pastOrders = orders?.filter(o => ['delivered', 'cancelled'].includes(o.status)) || []

  const handleLogin = async () => {
    hapticHeavy()
    try {
      const { loginWithLine } = await import('@/lib/auth')
      await loginWithLine()
    } catch {
      addToast({ type: 'error', title: 'เข้าสู่ระบบไม่สำเร็จ', message: 'กรุณาลองใหม่อีกครั้ง' })
    }
  }

  return (
    <div className="min-h-screen pb-32 relative mesh-bg-blue">

      {/* Ambient orbs */}
      <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden">
        <div
          className="absolute -top-20 -right-10 w-[300px] h-[300px] rounded-full animate-glow-pulse"
          style={{
            background: 'radial-gradient(circle, rgba(56,189,248,0.18) 0%, transparent 70%)',
            filter: 'blur(60px)',
          }}
        />
        <div
          className="absolute bottom-1/3 -left-16 w-[200px] h-[200px] rounded-full"
          style={{
            background: 'radial-gradient(circle, rgba(59,130,246,0.10) 0%, transparent 70%)',
            filter: 'blur(48px)',
          }}
        />
      </div>

      <Container className="py-4 relative z-10 space-y-5 max-w-2xl mx-auto px-4">

        {/* ── Premium Header ── */}
        <div className="flex items-center justify-between pt-1">
          <motion.button
            type="button"
            aria-label="ย้อนกลับ"
            whileTap={{ scale: 0.88 }}
            onClick={() => { hapticLight(); navigate(-1) }}
            className="w-11 h-11 rounded-[18px] flex items-center justify-center cursor-pointer"
            style={{ background: 'var(--bg-card)', border: '1px solid var(--border-soft)' }}
          >
            <ArrowLeft className="w-5 h-5 text-gray-300" aria-hidden="true" />
          </motion.button>

          <div className="text-center">
            <h1 className="text-[17px] font-black tracking-tight text-white flex items-center justify-center gap-2">
              <ClipboardList className="w-4.5 h-4.5 text-sky-400" />
              <span>ประวัติออเดอร์</span>
            </h1>
            <p className="text-[9px] font-black uppercase tracking-[0.14em] text-sky-400 mt-0.5">
              Order History
            </p>
          </div>

          <motion.button
            type="button"
            aria-label="โหลดข้อมูลใหม่"
            aria-busy={isRefetching}
            whileTap={{ scale: 0.88 }}
            onClick={() => { hapticMedium(); refetch() }}
            className={cn(
              'w-11 h-11 rounded-[18px] flex items-center justify-center cursor-pointer',
              isRefetching ? 'opacity-40 pointer-events-none' : ''
            )}
            style={{ background: 'var(--bg-card)', border: '1px solid var(--border-soft)' }}
          >
            <RefreshCw
              className={cn('w-4.5 h-4.5 text-gray-300', isRefetching ? 'animate-spin' : '')}
              aria-hidden="true"
            />
          </motion.button>
        </div>

        {/* ── Guest Banner ── */}
        <AnimatePresence>
          {isGuest && (
            <motion.div
              initial={{ opacity: 0, height: 0, scale: 0.95 }}
              animate={{ opacity: 1, height: 'auto', scale: 1 }}
              exit={{ opacity: 0, height: 0 }}
            >
              <div
                className="rounded-[22px] p-4 relative overflow-hidden shine-sweep"
                style={{
                  background: 'linear-gradient(135deg, rgba(56,189,248,0.08), rgba(14,165,233,0.04))',
                  border: '1px solid rgba(56,189,248,0.18)',
                }}
              >
                <div className="flex items-center justify-between relative z-10">
                  <div className="flex-1">
                    <p className="font-black text-white text-sm mb-0.5">ผู้เยี่ยมชมระบบ</p>
                    <p className="text-[10px] font-bold text-sky-300/70">
                      เชื่อมต่อ LINE เพื่อบันทึกประวัติถาวร
                    </p>
                  </div>
                  <motion.button
                    type="button"
                    whileTap={{ scale: 0.92 }}
                    onClick={handleLogin}
                    aria-label="เข้าสู่ระบบด้วย LINE"
                    className="text-white px-4 py-2.5 rounded-full font-black text-xs flex items-center gap-1.5 flex-shrink-0 cursor-pointer"
                    style={{
                      background: 'linear-gradient(135deg, #00C900, #00A000)',
                      boxShadow: '0 6px 16px rgba(0,185,0,0.35)',
                    }}
                  >
                    <Smartphone className="w-3.5 h-3.5" aria-hidden="true" />
                    Login
                  </motion.button>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* ── Active/Past Order Stats ── */}
        {!isLoading && orders && orders.length > 0 && (
          <div className="grid grid-cols-2 gap-3">
            <div
              className="rounded-[20px] p-4 text-center"
              style={{
                background: 'rgba(56,189,248,0.06)',
                border: '1px solid rgba(56,189,248,0.16)',
              }}
            >
              <p className="text-2xl font-black text-sky-300 num-display">{activeOrders.length}</p>
              <p className="text-[9px] font-black uppercase tracking-wider text-sky-400/70 mt-0.5">กำลังดำเนินการ</p>
            </div>
            <div
              className="rounded-[20px] p-4 text-center"
              style={{
                background: 'var(--bg-card)',
                border: '1px solid var(--border-soft)',
              }}
            >
              <p className="text-2xl font-black text-white num-display">{pastOrders.length}</p>
              <p className="text-[9px] font-black uppercase tracking-wider mt-0.5" style={{ color: 'var(--text-muted)' }}>
                เสร็จสิ้นแล้ว
              </p>
            </div>
          </div>
        )}

        {/* ── Orders Content ── */}
        {isLoading ? (
          <div className="space-y-4">
            <OrderCardSkeleton />
            <OrderCardSkeleton />
          </div>
        ) : !orders || orders.length === 0 ? (
          <motion.div
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            className="rounded-[28px] p-10 text-center"
            style={{
              background: 'var(--bg-card)',
              border: '1px solid var(--border-soft)',
            }}
          >
            <div
              className="w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4"
              style={{ background: 'var(--bg-surface)', border: '1px solid var(--border-soft)' }}
            >
              <PackageX className="w-8 h-8 text-gray-500" />
            </div>
            <h2 className="font-black text-white text-lg mb-2">ยังไม่มีประวัติการสั่งซื้อ</h2>
            <p className="text-xs font-medium mb-6" style={{ color: 'var(--text-secondary)' }}>
              คุณยังไม่ได้ทำการสั่งซื้อรายการอาหารใดๆ
            </p>
            <motion.button
              whileTap={{ scale: 0.95 }}
              onClick={() => navigate('/')}
              className="btn-brand px-6 py-3 rounded-full font-black text-xs inline-flex items-center gap-2 cursor-pointer"
            >
              <Zap className="w-4 h-4" />
              สั่งอาหารเลย!
            </motion.button>
          </motion.div>
        ) : (
          <motion.div variants={staggerList} initial="hidden" animate="visible" className="space-y-6">

            {/* Active Orders Section */}
            {activeOrders.length > 0 && (
              <motion.div variants={slideUpItem} className="space-y-3">
                <div className="flex items-center justify-between px-1">
                  <div className="flex items-center gap-2.5">
                    <span className="status-live" />
                    <h2 className="text-sm font-black text-white">กำลังดำเนินการ ({activeOrders.length})</h2>
                  </div>
                  <span className="badge-blue">Live</span>
                </div>
                <div className="space-y-3">
                  {activeOrders.map(order => (
                    <OrderCard
                      key={order.id}
                      order={order}
                      onClick={() => navigate(`/orders/${order.id}${order.trackingToken ? `?token=${order.trackingToken}` : ''}`)}
                    />
                  ))}
                </div>
              </motion.div>
            )}

            {/* Past Orders Section */}
            {pastOrders.length > 0 && (
              <motion.div variants={slideUpItem} className="space-y-3">
                <div className="flex items-center justify-between px-1">
                  <div className="flex items-center gap-2">
                    <Clock className="w-4 h-4 text-gray-500" />
                    <h2 className="text-sm font-black text-white">ประวัติที่ผ่านมา ({pastOrders.length})</h2>
                  </div>
                </div>
                <div className="space-y-3">
                  {pastOrders.map(order => (
                    <OrderCard
                      key={order.id}
                      order={order}
                      onClick={() => navigate(`/orders/${order.id}${order.trackingToken ? `?token=${order.trackingToken}` : ''}`)}
                    />
                  ))}
                </div>
              </motion.div>
            )}

          </motion.div>
        )}
      </Container>
    </div>
  )
}
